<?php
declare(strict_types=1);
namespace App\Services; use App\Core\Database;
final class DashboardService {
 public function stats(array $actor):array{$pdo=Database::connection();$admin=in_array($actor['role_name']??'', ['Super Admin','Admin'], true);if($admin){$totalUsers=(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();$activeUsers=(int)$pdo->query('SELECT COUNT(*) FROM users WHERE status="active"')->fetchColumn();$total=(float)$pdo->query('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE status="posted"')->fetchColumn();$month=(float)$pdo->query('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE status="posted" AND DATE_FORMAT(expense_date,"%Y-%m")=DATE_FORMAT(CURDATE(),"%Y-%m")')->fetchColumn();$categories=(int)$pdo->query('SELECT COUNT(*) FROM categories')->fetchColumn();$accounts=(int)$pdo->query('SELECT COUNT(*) FROM accounts')->fetchColumn();return compact('totalUsers','activeUsers','total','month','categories','accounts')+['admin'=>true,'byCategory'=>[],'monthly'=>[]];}
 $userId=(int)$actor['id'];$q=function(string $sql,array $p=[])use($pdo){$s=$pdo->prepare($sql);$s->execute($p);return $s->fetchColumn();};$total=(float)$q('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE user_id=? AND status="posted"',[$userId]);$month=(float)$q('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE user_id=? AND status="posted" AND DATE_FORMAT(expense_date,"%Y-%m")=DATE_FORMAT(CURDATE(),"%Y-%m")',[$userId]);$today=(float)$q('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE user_id=? AND status="posted" AND expense_date=CURDATE()',[$userId]);$budget=(float)$q('SELECT COALESCE(SUM(budget_amount),0) FROM budgets WHERE user_id=? AND status="active" AND start_date<=CURDATE() AND end_date>=CURDATE()',[$userId]);$balance=(float)$q('SELECT COALESCE(SUM(current_balance),0) FROM accounts WHERE user_id=? AND status="active"',[$userId]);$byCat=$pdo->prepare('SELECT c.name label,COALESCE(SUM(e.amount),0) value FROM expenses e JOIN categories c ON c.id=e.category_id WHERE e.user_id=? AND e.status="posted" GROUP BY c.id ORDER BY value DESC LIMIT 8');$byCat->execute([$userId]);$monthly=$pdo->prepare('SELECT DATE_FORMAT(expense_date,"%b") label,ROUND(SUM(amount),2) value FROM expenses WHERE user_id=? AND status="posted" AND expense_date>=DATE_SUB(CURDATE(),INTERVAL 11 MONTH) GROUP BY YEAR(expense_date),MONTH(expense_date) ORDER BY YEAR(expense_date),MONTH(expense_date)');$monthly->execute([$userId]);return compact('total','month','today','budget','balance')+['admin'=>false,'remaining'=>$budget-$month,'byCategory'=>$byCat->fetchAll(),'monthly'=>$monthly->fetchAll()];}
}
